command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "6e6e1a66cf69c7158f2bfa2be329341b72d5b388") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "0677f3db614646714ed8100d3a82f45de5fc438d") { throw "candidate branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "0677f3db614646714ed8100d3a82f45de5fc438d") { throw "candidate mismatch" }
$allowed=@(".agent-policy/PROJECT.md","AGENTS.md","docs/development/AGENT_EFFICIENCY.md","tests/winui/test_large_owned_folder_gui.py","tests/winui/test_remote_windows_task_contract.py")
$delta=@(git diff --name-only b04119082799dc8e064ae3bd696f1e18fb76f085..HEAD)
$unexpected=@($delta | Where-Object { $_ -notin $allowed })
if($unexpected.Count -ne 0){ throw ("product changed since validated Release build: " + ($unexpected -join ", ")) }
python -X utf8 -m py_compile tests\winui\test_large_owned_folder_gui.py
if ($LASTEXITCODE -ne 0) { throw "large-folder GUI harness syntax failed" }
if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe" -PathType Leaf)) { throw "previously validated Release artifact missing" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 20500 --configuration Release --browse-over-complete-model
if ($LASTEXITCODE -ne 0) { throw "indexed name sort/filter over-20k GUI acceptance failed" }
$source = "C:\dev\flyExplorer\logs\m23\large-name-index-over-20k-after.png"
$target = "C:\dev\flyExplorer\logs\remote-evidence"
if (!(Test-Path -LiteralPath $source -PathType Leaf)) { throw "indexed visual evidence image missing" }
New-Item -ItemType Directory -Force -Path $target | Out-Null
Get-ChildItem -LiteralPath $target -File -ErrorAction SilentlyContinue | Remove-Item -Force
Copy-Item -LiteralPath $source -Destination (Join-Path $target "large-name-index-over-20k-after.png")
Get-FileHash -Algorithm SHA256 -LiteralPath $source | ForEach-Object { "$($_.Path) $($_.Hash)" } | Set-Content -Encoding UTF8 -LiteralPath (Join-Path $target "large-name-index-sha256.txt")
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_KEYBOARD_GUI_PASS"
